func (d *VarietyDao) DelBlobs(key string) {
	if d.blobs == nil {
		return
	}
	if tx := nest.CurrentRollbackTx(); tx != nil && tx.Policy() == nest.RollbackUndo {
		old, existed := d.blobs.Get(key)
		d.recordUndoToken(tx, varietyDaoFieldBlobs, key, func() error {
			if existed {
				d.blobs.Set(key, old)
			}
			return nil
		})
	}
	if d.blobs.Delete(key) {
		d.markBlobsKeyDeleted(key)
	}
}

func (d *VarietyDao) RangeBlobs(f func(key string, val []byte) bool) {
	if d.blobs == nil || f == nil {
		return
	}
	// Each value handed to f is a copy, for the same reason GetBlobs copies.
	d.blobs.Range(func(key string, val []byte) bool { return f(key, append(val[:0:0], val...)) })
}

func (d *VarietyDao) BlobsLen() int {
	if d.blobs == nil {
		return 0
	}
	return d.blobs.Len()
}

func (d *VarietyDao) SetEnvelope(v Envelope) {
	if tx := nest.CurrentRollbackTx(); tx != nil && tx.Policy() == nest.RollbackUndo {
		old := d.envelope
		d.recordUndo(tx, varietyDaoFieldEnvelope, func() error {
			d.envelope = old
			d.envelope.bindDirty(daoDirtyOwner{holder: d, field: varietyDaoFieldEnvelope}, d.markEnvelopeChange)
			return nil
		})
	}
	d.envelope = v
	d.envelope.bindDirty(daoDirtyOwner{holder: d, field: varietyDaoFieldEnvelope}, d.markEnvelopeChange)
	d.markEnvelopeDirty()
}

func (d *VarietyDao) SetEnabled(v bool) {
	if d.enabled != v {
		if tx := nest.CurrentRollbackTx(); tx != nil && tx.Policy() == nest.RollbackUndo {
			old := d.enabled
			d.recordUndo(tx, varietyDaoFieldEnabled, func() error { d.enabled = old; return nil })
		}
		d.enabled = v
		d.markEnabledDirty()
	}
}

func (d *VarietyDao) SetCounter(v uint64) {
	if d.counter != v {
		if tx := nest.CurrentRollbackTx(); tx != nil && tx.Policy() == nest.RollbackUndo {
			old := d.counter
			d.recordUndo(tx, varietyDaoFieldCounter, func() error { d.counter = old; return nil })
		}
		d.counter = v
		d.markCounterDirty()
	}
}

