// --- Marshal (persist fields) ---

// CaptureRollbackState is side-effect free and includes transient and
// sync-only fields. Persistence changes live in RollbackTx, not in the DAO.
func (d *VarietyDao) CaptureRollbackState() ([]byte, error) {
	return bson.Marshal(d.rollbackDoc())
}

func (d *VarietyDao) RestoreRollbackState(raw []byte) error {
	var doc varietyDaoRollbackDoc
	if err := bson.Unmarshal(raw, &doc); err != nil {
		return err
	}
	d.setPersistDoc(doc.PersistDoc)
	d.syncOnly = doc.SyncOnly
	d.neither = doc.Neither
	d.setPendingRawMap(doc.Pending)
	d.enabled = doc.Enabled
	d.counter = doc.Counter
	d.Init()
	return nil
}

// varietyDaoRollbackDoc is the in-memory rollback snapshot, never stored:
// the persisted document plus the fields that are not persisted, under their
// keys.
type varietyDaoRollbackDoc struct {
	PersistDoc varietyDaoPersistDoc `bson:"_persisted"`
	SyncOnly   int64                `bson:"sync_only"`
	Neither    int64                `bson:"neither"`
	Pending    map[int32]int64      `bson:"pending"`
	Enabled    bool                 `bson:"enabled"`
	Counter    uint64               `bson:"counter"`
}

func (d *VarietyDao) rollbackDoc() varietyDaoRollbackDoc {
	return varietyDaoRollbackDoc{
		PersistDoc: d.persistDoc(),
		SyncOnly:   d.syncOnly,
		Neither:    d.neither,
		Pending:    d.varietyDaoPendingRawMap(),
		Enabled:    d.enabled,
		Counter:    d.counter,
	}
}

// persistDoc is the full document of the current state; setPersistDoc puts a
// decoded one back (identity and persisted fields; the caller runs Init).
func (d *VarietyDao) persistDoc() varietyDaoPersistDoc {
	return varietyDaoPersistDoc{
		ID:            d.id,
		SchemaVersion: VarietyDaoSchemaVersion,
		PersistOnly:   d.persistOnly,
		FastItems:     d.varietyDaoFastItemsRawMap(),
		ShardedTags:   d.varietyDaoShardedTagsRawMap(),
		ResultJSON:    d.resultJSON,
		Blobs:         d.varietyDaoBlobsRawMap(),
		Envelope:      d.envelope.bsonDoc(),
	}
}

func (d *VarietyDao) setPersistDoc(doc varietyDaoPersistDoc) {
	d.id = doc.ID
	d.persistOnly = doc.PersistOnly
	d.setFastItemsRawMap(doc.FastItems)
	d.setShardedTagsRawMap(doc.ShardedTags)
	d.resultJSON = doc.ResultJSON
	d.setBlobsRawMap(doc.Blobs)
	d.envelope = envelopeFromBSONDoc(doc.Envelope)
}

func (d *VarietyDao) marshalCommitState() ([]byte, error) {
	return bson.Marshal(d.persistDoc())
}

func (d *VarietyDao) PrepareMutation(change nest.PersistChange) (dataengine.Mutation, error) {
	version := d.tracker.Version()
	mutation := dataengine.Mutation{
		Key: dataengine.DocumentKey{
			Database: d.DbName(), Scope: dataengine.DatabaseScope(d.DbScope()),
			Resource: d.CollName(), ID: d.Id(),
		},
		Kind: dataengine.MutationPatch, ExpectedVersion: version, NextVersion: version + 1,
		Mask: change.Mask, Schema: VarietyDaoSchemaVersion, Codec: "bson-v2",
	}
	if change.Delete {
		mutation.Kind = dataengine.MutationDelete
		return mutation, nil
	}
	if version == 0 || change.Mask == dataengine.AllFields {
		data, err := d.marshalCommitState()
		if err != nil {
			return dataengine.Mutation{}, fmt.Errorf("prepare put %s/%d: %w", d.CollName(), d.id, err)
		}
		mutation.Kind = dataengine.MutationPut
		mutation.Data = data
		return mutation, nil
	}
	patch, err := d.marshalPersistPatchBSON(change)
	if err != nil {
		return dataengine.Mutation{}, fmt.Errorf("prepare patch %s/%d: %w", d.CollName(), d.id, err)
	}
	mutation.Patch = patch
	return mutation, nil
}

func (d *VarietyDao) AcceptMutation(mutation dataengine.Mutation) error {
	return d.tracker.AcceptVersion(mutation.ExpectedVersion, mutation.NextVersion)
}

func (d *VarietyDao) Marshal() []byte {
	return d.MarshalPersist(dataengine.AllFields)
}

func (d *VarietyDao) MarshalPersist(mask uint64) []byte {
	return d.marshalPersistData(mask)
}

func (d *VarietyDao) marshalPersistData(mask uint64) []byte {
	_ = mask // full payload is used for inserts and safe fallback.
	data, err := d.marshalCommitState()
	if err != nil {
		// The interface has no error slot and a nil payload would be
		// persisted as silent data loss; a marshal failure here is a
		// programming error (unserializable state), so fail loudly and let
		// Data Engine WAL recovery owns the aftermath.
		panic(fmt.Errorf("VarietyDao: marshal persist data: %w", err))
	}
	return data
}

func (d *VarietyDao) persistChangeHasPath(change nest.PersistChange, field string) bool {
	prefix := field + "."
	for path := range change.Set {
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	for _, path := range change.Unset {
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	return false
}

func (d *VarietyDao) persistChangePathCovered(change nest.PersistChange, path string) bool {
	for field := range change.FullFields {
		prefix := field + "."
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	return false
}

func (d *VarietyDao) marshalPersistPatchBSON(change nest.PersistChange) (dataengine.FieldPatch, error) {
	set := make(map[string]any, len(change.Set)+len(change.FullFields))
	unset := append([]string(nil), change.Unset...)
	root := change.Paths.Root()
	if change.Mask&varietyDaoFieldPersistOnly != 0 {
		node := root.Child(dataengine.SyncStep{Field: 2})
		_, full := change.FullFields["persist_only"]
		if !root.Full() && node != nil && !full {
			d.appendPersistOnlyPersist(set, &unset, "persist_only", node)
		} else {
			set["persist_only"] = d.persistOnly
		}
	}
	if change.Mask&varietyDaoFieldFastItems != 0 {
		node := root.Child(dataengine.SyncStep{Field: 6})
		_, full := change.FullFields["fast_items"]
		if !root.Full() && node != nil && !full {
			d.appendFastItemsPersist(set, &unset, "fast_items", node)
		} else {
			_, full := change.FullFields["fast_items"]
			if full || !d.persistChangeHasPath(change, "fast_items") {
				set["fast_items"] = d.varietyDaoFastItemsRawMap()
			}
		}
	}
	if change.Mask&varietyDaoFieldShardedTags != 0 {
		node := root.Child(dataengine.SyncStep{Field: 7})
		_, full := change.FullFields["sharded_tags"]
		if !root.Full() && node != nil && !full {
			d.appendShardedTagsPersist(set, &unset, "sharded_tags", node)
		} else {
			_, full := change.FullFields["sharded_tags"]
			if full || !d.persistChangeHasPath(change, "sharded_tags") {
				set["sharded_tags"] = d.varietyDaoShardedTagsRawMap()
			}
		}
	}
	if change.Mask&varietyDaoFieldResultJSON != 0 {
		node := root.Child(dataengine.SyncStep{Field: 8})
		_, full := change.FullFields["result_json"]
		if !root.Full() && node != nil && !full {
			d.appendResultJSONPersist(set, &unset, "result_json", node)
		} else {
			set["result_json"] = d.resultJSON
		}
	}
	if change.Mask&varietyDaoFieldBlobs != 0 {
		node := root.Child(dataengine.SyncStep{Field: 9})
		_, full := change.FullFields["blobs"]
		if !root.Full() && node != nil && !full {
			d.appendBlobsPersist(set, &unset, "blobs", node)
		} else {
			_, full := change.FullFields["blobs"]
			if full || !d.persistChangeHasPath(change, "blobs") {
				set["blobs"] = d.varietyDaoBlobsRawMap()
			}
		}
	}
	if change.Mask&varietyDaoFieldEnvelope != 0 {
		node := root.Child(dataengine.SyncStep{Field: 10})
		_, full := change.FullFields["envelope"]
		if !root.Full() && node != nil && !full {
			d.appendEnvelopePersist(set, &unset, "envelope", node)
		} else {
			set["envelope"] = d.envelope.bsonDoc()
		}
	}
	for path, value := range change.Set {
		if !d.persistChangePathCovered(change, path) {
			set[path] = value
		}
	}
	var raw []byte
	if len(set) != 0 {
		keys := make([]string, 0, len(set))
		for path := range set {
			keys = append(keys, path)
		}
		sort.Strings(keys)
		doc := make(bson.D, 0, len(keys))
		for _, path := range keys {
			doc = append(doc, bson.E{Key: path, Value: set[path]})
		}
		var err error
		raw, err = bson.Marshal(doc)
		if err != nil {
			return dataengine.FieldPatch{}, err
		}
	}
	return dataengine.FieldPatch{SetBSON: raw, Unset: unset}, nil
}

func (value *VarietyDao) appendPersistOnlyPersist(set map[string]any, unset *[]string, path string, change *dataengine.SyncChange) {
	if change.Full() {
		set[path] = value.persistOnly
		return
	}
	set[path] = value.persistOnly
	return
}
func (value *VarietyDao) appendFastItemsPersist(set map[string]any, unset *[]string, path string, change *dataengine.SyncChange) {
	if change.Full() {
		set[path] = value.varietyDaoFastItemsRawMap()
		return
	}
	if value.fastItems == nil || change.ReplacementCount() >= value.fastItems.Len() {
		set[path] = value.varietyDaoFastItemsRawMap()
		return
	}
	for step := range change.Children {
		if _, ok := dataengine.MapPatchPath(path, step.Key); !ok {
			set[path] = value.varietyDaoFastItemsRawMap()
			return
		}
	}
	for step, child := range change.Children {
		key := step.Key.(int64)
		target, _ := dataengine.MapPatchPath(path, key)
		item, exists := value.fastItems.Get(key)
		if !exists {
			*unset = append(*unset, target)
			continue
		}
		_ = child
		set[target] = item
	}
}
