// PersistFieldNames implements nest.PersistFieldNamer: the stored names of the
// persistent fields in mask. A durability=memory transaction that changes one
// of them fails and names them.
func (d *VarietyDao) PersistFieldNames(mask uint64) []string {
	var names []string
	if mask&varietyDaoFieldPersistOnly != 0 {
		names = append(names, "persist_only")
	}
	if mask&varietyDaoFieldFastItems != 0 {
		names = append(names, "fast_items")
	}
	if mask&varietyDaoFieldShardedTags != 0 {
		names = append(names, "sharded_tags")
	}
	if mask&varietyDaoFieldResultJSON != 0 {
		names = append(names, "result_json")
	}
	if mask&varietyDaoFieldBlobs != 0 {
		names = append(names, "blobs")
	}
	if mask&varietyDaoFieldEnvelope != 0 {
		names = append(names, "envelope")
	}
	return names
}

// VarietyDaoSyncFields is the vocabulary for this DAO's dirty masks: which
// field each bit means, and what it is called on the wire.
//
// It exists because the bit constants themselves are unexported — a packer
// written outside this package can hand a mask to MarshalSync but cannot look
// inside it, which is fine until the game has its own client protocol and has
// to decide what changed.
//
// **Bit is stable only within this generated schema.** Anything that outlives
// the build — a stored projection, a client's cached layout — keys on Name or
// WireName. The bits are not an ABI.
func VarietyDaoSyncFields() []dataengine.SyncFieldMeta {
	return []dataengine.SyncFieldMeta{
		{Name: "SyncOnly", WireName: "sync_only", Bit: varietyDaoFieldSyncOnly},
		{Name: "FastItems", WireName: "fast_items", Bit: varietyDaoFieldFastItems},
		{Name: "ShardedTags", WireName: "sharded_tags", Bit: varietyDaoFieldShardedTags},
		{Name: "ResultJSON", WireName: "result_json", Bit: varietyDaoFieldResultJSON},
		{Name: "Blobs", WireName: "blobs", Bit: varietyDaoFieldBlobs},
		{Name: "Envelope", WireName: "envelope", Bit: varietyDaoFieldEnvelope},
		{Name: "Enabled", WireName: "enabled", Bit: varietyDaoFieldEnabled},
		{Name: "Counter", WireName: "counter", Bit: varietyDaoFieldCounter},
	}
}

// SyncFields is the same table, reachable from a value — a packer holds the
// DAO, not the package.
func (d *VarietyDao) SyncFields() []dataengine.SyncFieldMeta { return VarietyDaoSyncFields() }

// MarshalSync 编码字段级 PB patch：包装存在表示本次覆盖，包含零值与空容器。
// 持久化、回滚快照仍使用 BSON。
func (d *VarietyDao) MarshalSync(mask uint64) []byte {
	return d.marshalSyncPB(mask)
}

func (d *VarietyDao) ApplySync(raw []byte) error {
	return d.applySyncPB(raw)
}

// --- Unmarshal ---

func (d *VarietyDao) Unmarshal(raw []byte) error {
	var doc varietyDaoPersistDoc
	if err := bson.Unmarshal(raw, &doc); err != nil {
		return err
	}
	d.setPersistDoc(doc)
	d.Init()
	return nil
}

// RestorePersisted is the single production hydration path used by the
// Data Engine aggregate repository. Schema must match before decoding or changing the tracker.
// A stored key varietyDaoPersistDoc does not declare is reported (once per key per
// process) and the document still loads without it: the value is not read,
// and the next full write of the document drops the key (DESIGN-TODO D13).
func (d *VarietyDao) RestorePersisted(raw []byte, schemaVersion uint32, version uint64) error {
	if schemaVersion != VarietyDaoSchemaVersion {
		return fmt.Errorf("%w: dao VarietyDao stored=%d runtime=%d", dataengine.ErrSchemaMismatch, schemaVersion, VarietyDaoSchemaVersion)
	}
	varietyDaoStoredKeys.WarnUnknown(raw)
	if err := d.Unmarshal(raw); err != nil {
		return err
	}
	d.tracker.SetVersion(version)
	d.CleanDirty()
	return nil
}

